#include <iostream> `n#include <fstream>`n#include <string>`n`nnamespace malyshev {`n    const int error_args = 1;`n    const int error_data = 2;`n    const int max_size = 10000;`n    const std::string elements_more_10000 = "elements more 10000";`n`n    int process_fix_massive(std::ifstream& ifile, int* matrix, int& rows, int& cols);`n    int process_dynamic_massive(std::ifstream& ifile, int*& matrix, int& rows, int& cols);`n    int long_ser_cols(int* matrix, int rows, int cols);`n}`n`nint main(int argc, char* argv[])`n{`n    if (argc != 4) {`n        std::cerr << "The number of command-line arguments does not match the specification "`n            << "or the first parameter cannot be interpreted "`n            << "as the indicated job numbers\n";`n        return malyshev::error_args;`n    }`n`n    std::string num = argv[1];`n    std::string input_filename = argv[2];`n    std::string output_filename = argv[3];`n`n`n    int rows = 0;`n    int cols = 0;`n    int res = 0;`n    int read_status = 0;`n    int static_matrix[10000];`n    int* dynamic_matrix = nullptr;`n`n    std::ifstream file(input_filename);`n`n    if (file.fail())`n    {`n        std::cerr << "cannot be interpreted as a two-dimensional array "`n            << "or the file is empty\n";`n        return malyshev::error_data;`n    }`n`n    if (num == "1")`n    {`n        read_status  = malyshev::process_fix_massive(file, static_matrix, rows, cols);`n    }`n`n    else if (num == "2")`n    {`n        read_status = malyshev::process_dynamic_massive(file, dynamic_matrix, rows, cols);`n    }`n`n    else`n    {`n        std::cerr << "The number of command-line arguments does not match the specification "`n            << "or the first parameter cannot be interpreted "`n            << "as the indicated job numbers\n";`n        file.close();`n        return malyshev::error_args;`n    }`n`n    file.close();`n`n    if (read_status != 0)`n    {`n        std::cerr << "cannot be interpreted as a two-dimensional array "`n            << "or the file is empty\n";`n        if (num == "2" && dynamic_matrix != nullptr) {`n            delete[] dynamic_matrix;`n        }`n        return read_status;`n    }`n`n    if (num == "1")`n    {`n        res = malyshev::long_ser_cols(static_matrix, rows, cols);`n    }`n    else if (num == "2")`n    {`n        res = malyshev::long_ser_cols(dynamic_matrix, rows, cols);`n    }`n`n    std::ofstream outfile(output_filename);`n    if (outfile.fail())`n    {`n        std::cerr << "The file was not saved\n";`n        if (num == "2") {`n            delete[] dynamic_matrix;`n        }`n        return malyshev::error_args;`n    }`n`n    outfile << res << "\n";`n    outfile.close();`n`n    if (num == "2") {`n        delete[] dynamic_matrix;`n    }`n    return 0;`n}`n`nnamespace malyshev{`n    int process_fix_massive(std::ifstream& ifile, int* matrix, int& rows, int& cols)`n    {`n        ifile >> rows >> cols;`n        if (ifile.fail())`n        {`n            return error_data;`n        }`n        if (rows * cols > max_size)`n        {`n            std::cerr << "elements more 10000\n";`n            return error_data;`n        }`n        int total_el = rows * cols;`n        for (size_t i = 0; i < total_el;i++)`n        {`n            ifile >> matrix[i];`n            if (ifile.fail())`n            {`n                return error_data;`n            }`n        }`n        char extra;`n        ifile >> extra;`n        if (!ifile.fail())`n        {`n            return error_data;`n        }`n        return 0;`n    }`n`n    int process_dynamic_massive(std::ifstream& ifile, int*& matrix, int& rows, int& cols)`n    {`n        ifile >> rows >> cols;`n        if (ifile.fail())`n        {`n            return error_data;`n        }`n        if (rows < 0 || cols < 0)`n        {`n            return error_data;`n        }`n        matrix = new int[rows * cols];`n        int total_el = rows * cols;`n        for (int i = 0; i < total_el; i++)`n        {`n            ifile >> matrix[i];`n            if (ifile.fail())`n            {`n                return error_data;`n            }`n        }`n        char extra;`n        ifile >> extra;`n        if (!ifile.fail())`n        {`n            return error_data;`n        }`n        return 0;`n    }`n`n    int long_ser_cols(int* matrix, int rows, int cols)`n    {`n        if (rows <= 0 || cols <= 0)`n        {`n            return 0;`n        }`n`n        int max_ser_len = 0;`n        int max_cols = 0;`n`n        for (size_t i = 0; i < cols; i++)`n        {`n            int current_sers = 1;`n            int max_in_col = 1;`n`n            for (size_t j = 1; j < rows; j++)`n            {`n                if (matrix[j * cols + i] == matrix[(j - 1) * cols + i])`n                {`n                    current_sers++;`n                }`n                else`n                {`n                    current_sers = 1;`n                }`n                if (current_sers > max_in_col)`n                {`n                    max_in_col = current_sers;`n                }`n            }`n            if (max_in_col > max_ser_len)`n            {`n                max_ser_len = max_in_col;`n                max_cols = i + 1;`n            }`n        }`n        return max_cols;`n    }`n}`n